import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { Bar, Doughnut } from 'react-chartjs-2';
import { Chart as ChartJS, ArcElement, CategoryScale, LinearScale, BarElement, Tooltip, Legend } from 'chart.js';
import Navbar from '../components/Navbar';
import { getAnalytics, getAllInternships } from '../services/api';

ChartJS.register(ArcElement, CategoryScale, LinearScale, BarElement, Tooltip, Legend);

const chartDefaults = {
  plugins: { legend: { labels: { color: '#9090b0' } } },
  scales: { x: { ticks: { color: '#9090b0' }, grid: { color: 'rgba(255,255,255,0.05)' } },
             y: { ticks: { color: '#9090b0' }, grid: { color: 'rgba(255,255,255,0.05)' }, beginAtZero: true } },
};

export default function AdminDashboard() {
  const [stats, setStats] = useState({});
  const [internships, setInternships] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    Promise.all([getAnalytics(), getAllInternships()])
      .then(([a, i]) => { setStats(a.data); setInternships(i.data); })
      .catch(() => {})
      .finally(() => setLoading(false));
  }, []);

  const barData = {
    labels: ['Users', 'Students', 'Internships', 'Applications', 'Accepted', 'Rejected'],
    datasets: [{
      label: 'Count',
      data: [stats.totalUsers||0, stats.totalStudents||0, stats.totalInternships||0,
             stats.totalApplications||0, stats.accepted||0, stats.rejected||0],
      backgroundColor: ['#7c6bff','#a78bfa','#22c55e','#3b82f6','#22c55e','#ef4444'],
      borderRadius: 8,
    }],
  };

  const donutData = {
    labels: ['Applied', 'Under Review', 'Shortlisted', 'Interview', 'Accepted', 'Rejected'],
    datasets: [{
      data: [stats.applied||0, 0, stats.shortlisted||0, stats.interview||0, stats.accepted||0, stats.rejected||0],
      backgroundColor: ['#3b82f6','#f59e0b','#7c6bff','#ec4899','#22c55e','#ef4444'],
      borderWidth: 0,
    }],
  };

  const topInternships = [...internships].sort((a, b) => (b.applicationCount||0) - (a.applicationCount||0)).slice(0, 5);

  if (loading) return <><Navbar /><div className="page"><div className="skeleton" style={{ height: '400px', borderRadius: '14px' }} /></div></>;

  return (
    <>
      <Navbar />
      <div className="page">
        <div className="page-header">
          <h1 className="page-title">Admin Dashboard</h1>
          <div style={{ display: 'flex', gap: '10px' }}>
            <Link to="/admin/internships" className="btn btn-primary btn-sm">+ Add Internship</Link>
          </div>
        </div>

        {/* Stats */}
        <div className="stats-grid">
          {[
            { label: 'Total Users', value: stats.totalUsers||0, color: 'var(--accent2)' },
            { label: 'Students', value: stats.totalStudents||0, color: 'var(--blue)' },
            { label: 'Internships', value: stats.totalInternships||0, color: 'var(--green)' },
            { label: 'Applications', value: stats.totalApplications||0, color: 'var(--amber)' },
            { label: 'Accepted', value: stats.accepted||0, color: 'var(--green)' },
            { label: 'Rejected', value: stats.rejected||0, color: 'var(--red)' },
          ].map(s => (
            <div key={s.label} className="stat-card">
              <div className="num" style={{ color: s.color }}>{s.value}</div>
              <div className="lbl">{s.label}</div>
            </div>
          ))}
        </div>

        {/* Charts */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1.5rem', marginBottom: '2rem' }}>
          <div className="card">
            <h3 style={{ marginBottom: '1rem', fontSize: '1rem' }}>Overview</h3>
            <Bar data={barData} options={{ ...chartDefaults, responsive: true, plugins: { ...chartDefaults.plugins, legend: { display: false } } }} />
          </div>
          <div className="card">
            <h3 style={{ marginBottom: '1rem', fontSize: '1rem' }}>Application Status</h3>
            <div style={{ maxHeight: '240px', display: 'flex', justifyContent: 'center' }}>
              <Doughnut data={donutData} options={{ responsive: true, plugins: { legend: { position: 'right', labels: { color: '#9090b0', font: { size: 11 } } } } }} />
            </div>
          </div>
        </div>

        {/* Quick links */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit,minmax(220px,1fr))', gap: '1rem', marginBottom: '2rem' }}>
          {[
            { label: 'Manage Internships', desc: `${stats.totalInternships||0} active listings`, link: '/admin/internships', icon: '💼' },
            { label: 'Review Applications', desc: `${stats.totalApplications||0} total applications`, link: '/admin/applications', icon: '📋' },
            { label: 'Manage Users', desc: `${stats.totalStudents||0} students registered`, link: '/admin/users', icon: '👥' },
          ].map(q => (
            <Link key={q.label} to={q.link} className="card card-hover" style={{ display: 'block' }}>
              <div style={{ fontSize: '1.8rem', marginBottom: '8px' }}>{q.icon}</div>
              <h3 style={{ fontSize: '1rem', marginBottom: '4px' }}>{q.label}</h3>
              <p style={{ fontSize: '0.82rem', color: 'var(--text2)' }}>{q.desc}</p>
            </Link>
          ))}
        </div>

        {/* Top internships */}
        <div className="card">
          <h3 style={{ marginBottom: '1rem', fontSize: '1rem' }}>Most Applied Internships</h3>
          <div className="table-wrap">
            <table>
              <thead><tr><th>Role</th><th>Company</th><th>Applications</th><th>Views</th><th>Status</th></tr></thead>
              <tbody>
                {topInternships.map(i => (
                  <tr key={i.id}>
                    <td style={{ fontWeight: 500 }}>{i.role}</td>
                    <td>{i.companyName}</td>
                    <td>{i.applicationCount || 0}</td>
                    <td>{i.viewCount || 0}</td>
                    <td><span className={`badge ${i.status === 'ACTIVE' ? 'badge-accepted' : 'badge-rejected'}`}>{i.status}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </>
  );
}
